PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS categories(id INTEGER PRIMARY KEY,parent_id INTEGER REFERENCES categories(id) ON DELETE SET NULL,name TEXT NOT NULL, name_en TEXT DEFAULT '',slug TEXT NOT NULL UNIQUE,description TEXT DEFAULT '',cover_url TEXT DEFAULT '',sort_order INTEGER DEFAULT 0,status INTEGER DEFAULT 1,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS videos(id INTEGER PRIMARY KEY,uuid TEXT NOT NULL UNIQUE,title TEXT NOT NULL,title_en TEXT DEFAULT '',original_title TEXT DEFAULT '',slug TEXT NOT NULL UNIQUE,description TEXT DEFAULT '',description_en TEXT DEFAULT '',cover_url TEXT DEFAULT '',duration INTEGER NOT NULL DEFAULT 0 CHECK(duration>=0),category_id INTEGER REFERENCES categories(id) ON DELETE SET NULL,language TEXT DEFAULT '',release_date TEXT DEFAULT '',view_count INTEGER NOT NULL DEFAULT 0,play_count INTEGER NOT NULL DEFAULT 0,like_count INTEGER NOT NULL DEFAULT 0,favorite_count INTEGER NOT NULL DEFAULT 0,is_featured INTEGER DEFAULT 0,is_pinned INTEGER DEFAULT 0,sort_order INTEGER DEFAULT 0,rights_status TEXT NOT NULL DEFAULT 'pending',rights_reference TEXT DEFAULT '',status INTEGER DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,published_at INTEGER);
CREATE TABLE IF NOT EXISTS source_providers(id INTEGER PRIMARY KEY,name TEXT NOT NULL,domain TEXT NOT NULL UNIQUE,embed_template TEXT DEFAULT '',source_type TEXT DEFAULT 'iframe',allowed_domains TEXT DEFAULT '[]',check_enabled INTEGER DEFAULT 1,enabled INTEGER DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS video_sources(id INTEGER PRIMARY KEY,video_id INTEGER NOT NULL REFERENCES videos(id) ON DELETE CASCADE,provider_id INTEGER REFERENCES source_providers(id) ON DELETE SET NULL,source_url TEXT NOT NULL UNIQUE,embed_url TEXT DEFAULT '',external_id TEXT DEFAULT '',source_type TEXT NOT NULL CHECK(source_type IN ('iframe','mp4','hls','external')),quality TEXT DEFAULT '',priority INTEGER DEFAULT 0,is_default INTEGER DEFAULT 0,status INTEGER DEFAULT 1,health_status TEXT DEFAULT 'unknown',http_status INTEGER,failure_count INTEGER DEFAULT 0,last_error TEXT DEFAULT '',last_checked_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tags(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE,name_en TEXT DEFAULT '',slug TEXT NOT NULL UNIQUE,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS video_tags(video_id INTEGER REFERENCES videos(id) ON DELETE CASCADE,tag_id INTEGER REFERENCES tags(id) ON DELETE CASCADE,PRIMARY KEY(video_id,tag_id));
CREATE TABLE IF NOT EXISTS video_stats_daily(id INTEGER PRIMARY KEY,video_id INTEGER NOT NULL REFERENCES videos(id) ON DELETE CASCADE,date TEXT NOT NULL,view_count INTEGER DEFAULT 0,play_count INTEGER DEFAULT 0,unique_visitors INTEGER DEFAULT 0,favorite_count INTEGER DEFAULT 0,report_count INTEGER DEFAULT 0,UNIQUE(video_id,date));
CREATE TABLE IF NOT EXISTS advertisements(id INTEGER PRIMARY KEY,name TEXT NOT NULL,provider TEXT DEFAULT 'Adsterra',position TEXT NOT NULL CHECK(position IN ('top','sidebar','below','grid')),ad_type TEXT DEFAULT 'iframe',ad_code TEXT NOT NULL,allowed_domains TEXT DEFAULT '[]',width INTEGER DEFAULT 728,height INTEGER DEFAULT 90,device_type TEXT DEFAULT 'all',enabled INTEGER DEFAULT 0,start_at INTEGER,end_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS import_tasks(id INTEGER PRIMARY KEY,status TEXT DEFAULT 'queued',total INTEGER NOT NULL DEFAULT 0,processed INTEGER DEFAULT 0,created_count INTEGER DEFAULT 0,duplicate_count INTEGER DEFAULT 0,failed_count INTEGER DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS import_task_items(id INTEGER PRIMARY KEY,task_id INTEGER REFERENCES import_tasks(id) ON DELETE CASCADE,source_url TEXT NOT NULL,payload TEXT NOT NULL,status TEXT DEFAULT 'queued',video_id INTEGER REFERENCES videos(id) ON DELETE SET NULL,error TEXT DEFAULT '',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS video_reports(id INTEGER PRIMARY KEY,video_id INTEGER REFERENCES videos(id) ON DELETE CASCADE,reason TEXT NOT NULL,details TEXT DEFAULT '',status TEXT DEFAULT 'open',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS operation_logs(id INTEGER PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,entity_id TEXT DEFAULT '',detail TEXT DEFAULT '',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS redirects(id INTEGER PRIMARY KEY,old_slug TEXT UNIQUE NOT NULL,video_id INTEGER NOT NULL REFERENCES videos(id) ON DELETE CASCADE,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS videos_public ON videos(status,rights_status,published_at DESC);
CREATE INDEX IF NOT EXISTS videos_category ON videos(category_id,status,published_at DESC);
CREATE INDEX IF NOT EXISTS videos_views ON videos(status,view_count DESC);
CREATE INDEX IF NOT EXISTS sources_video ON video_sources(video_id,priority,id);
CREATE INDEX IF NOT EXISTS sources_check ON video_sources(status,last_checked_at);
CREATE INDEX IF NOT EXISTS stats_date ON video_stats_daily(date,video_id);
CREATE INDEX IF NOT EXISTS tags_video ON video_tags(tag_id,video_id);
CREATE INDEX IF NOT EXISTS imports_queue ON import_task_items(status,task_id,id);
CREATE VIRTUAL TABLE IF NOT EXISTS videos_fts USING fts5(title,title_en,description,description_en,original_title,content='videos',content_rowid='id',tokenize='trigram');
CREATE TRIGGER IF NOT EXISTS videos_ai AFTER INSERT ON videos BEGIN INSERT INTO videos_fts(rowid,title,title_en,description,description_en,original_title) VALUES(new.id,new.title,new.title_en,new.description,new.description_en,new.original_title); END;
CREATE TRIGGER IF NOT EXISTS videos_ad AFTER DELETE ON videos BEGIN INSERT INTO videos_fts(videos_fts,rowid,title,title_en,description,description_en,original_title) VALUES('delete',old.id,old.title,old.title_en,old.description,old.description_en,old.original_title); END;
CREATE TRIGGER IF NOT EXISTS videos_au AFTER UPDATE OF title,title_en,description,description_en,original_title ON videos BEGIN INSERT INTO videos_fts(videos_fts,rowid,title,title_en,description,description_en,original_title) VALUES('delete',old.id,old.title,old.title_en,old.description,old.description_en,old.original_title); INSERT INTO videos_fts(rowid,title,title_en,description,description_en,original_title) VALUES(new.id,new.title,new.title_en,new.description,new.description_en,new.original_title); END;
CREATE TABLE IF NOT EXISTS api_nonces(key_id TEXT NOT NULL,nonce TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(key_id,nonce));
CREATE INDEX IF NOT EXISTS nonce_time ON api_nonces(created_at);
CREATE TABLE IF NOT EXISTS ranking_entries(board TEXT NOT NULL,video_id INTEGER NOT NULL REFERENCES videos(id) ON DELETE CASCADE,position INTEGER NOT NULL,PRIMARY KEY(board,video_id),UNIQUE(board,position));
CREATE TABLE IF NOT EXISTS snapshot_versions(name TEXT PRIMARY KEY,version INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sitemap_entries(video_id INTEGER PRIMARY KEY REFERENCES videos(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS video_seo(video_id INTEGER PRIMARY KEY REFERENCES videos(id) ON DELETE CASCADE,title TEXT,title_en TEXT,description TEXT,description_en TEXT);
CREATE TABLE IF NOT EXISTS import_requests(request_id TEXT PRIMARY KEY,task_id INTEGER REFERENCES import_tasks(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS source_policy(source_id INTEGER PRIMARY KEY REFERENCES video_sources(id) ON DELETE CASCADE,excluded INTEGER NOT NULL CHECK(excluded IN (0,1)));
INSERT OR IGNORE INTO source_policy SELECT id,1 FROM video_sources WHERE health_status='dead';
PRAGMA user_version=2;

CREATE TABLE IF NOT EXISTS distributed_media(media_key TEXT PRIMARY KEY,video_id INTEGER NOT NULL UNIQUE REFERENCES videos(id) ON DELETE CASCADE,revision INTEGER NOT NULL,action TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS video_lifecycle(video_id INTEGER PRIMARY KEY REFERENCES videos(id) ON DELETE CASCADE,state TEXT NOT NULL CHECK(state IN ('frozen','deleted')));
PRAGMA user_version=3;
